def _gov_panel(sym):
    """持仓面板 governance 字段：state / none / family / foreign（与 index.html 约定一致）。"""
    _, typ, _ = _gov_of(sym)
    if typ in ('中央国有企业', '地方国有企业'):
        return 'state'
    if typ == '无实际控制人':
        return 'none'
